let referenceIndex=null,referenceError='',referenceLimit=20,referenceTopic='';fetch('./bhimboy-index.json').then(r=>{if(!r.ok)throw Error('Index unavailable');return r.json()}).then(d=>{referenceIndex=d;if(state&&!formDirty)render()}).catch(()=>{referenceError='Reference index is unavailable. Open online once to cache it.';if(state&&!formDirty)render()});
const app=document.querySelector('#app');let events=[],state,device,route='today',selectedTopic=rights.id,step=0,subjectFilter='',search='',formDirty=false,remoteUpdate=false,quiz=null,timerHandle=null,saveTimer=null,navDepth=0,syncState={kind:'disconnected',message:'Saved on this device',at:''};
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const topicBy=id=>topics.find(t=>t.id===id)||{id,title:id||'General',subject:'Custom topic',paper:'',te:''};
const uid=()=>crypto.randomUUID();const dateLabel=d=>new Date(d+'T12:00:00Z').toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'});
let practiceScope='APPSC Group-I';
let upscQuery='',upscSubject='',upscConcept='',upscMode='resources',upscStage='',upscLimit=20;
const routes=[['today','◉','Today'],['library','▦','APPSC topic library'],['upsc','▦','UPSC resources'],['materials','▦','Imported collections'],['revisions','↻','Revision queue'],['practice','◷','Practice & mocks'],['ledger','▤','Mistake ledger'],['catalogue','▦','Related concepts'],['papers','▧','Paper vault'],['current','⊕','Current affairs'],['insights','▥','Progress'],['tutor','✦','Study tutor'],['settings','⚙','Settings & sync']];
const btn=(label,action,secondary=false,attrs='')=>`<button class="btn ${secondary?'secondary':''}" data-action="${action}" ${attrs}>${label}</button>`;
const link=(label,page,secondary=false,attrs='')=>`<a class="btn ${secondary?'secondary':''}" href="#${page}" ${attrs}>${label}</a>`;
const empty=(title,text,extra='')=>`<div class="empty"><strong>${title}</strong><p>${text}</p>${extra}</div>`;
const pill=(text,color='')=>`<span class="pill ${color}">${text}</span>`;
const safeURL=u=>{try{const x=new URL(u);return x.protocol==='https:'?esc(x.href):'#'}catch{return '#'}};
const field=(label,name,type='text',value='',extra='')=>`<div class="field"><label for="${name}">${label}</label><input id="${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`;
const topicSelect=(name='topic',value=selectedTopic)=>`<div class="field"><label for="${name}">Topic</label><select id="${name}" name="${name}">${topics.map(t=>`<option value="${t.id}" ${t.id===value?'selected':''}>${esc(t.title)}</option>`).join('')}</select></div>`;
const head=(kicker,title,sub,action='')=>`<div class="pagehead"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p class="subtitle">${sub}</p></div>${action}</div>`;
function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),5000)}
function pendingCount(){return vault.credentials?events.filter(e=>!vault.remote.has(e.id)).length:events.length}
const vault=new VaultSync({read:()=>events,merge:async incoming=>{const next=mergeEvents(events,incoming);await putEvents(incoming);events=next;state=reduce(events);if(incoming.length){channel?.postMessage('saved');refreshFromRemote()}},status:(kind,message,at)=>{syncState={kind,message,at:at||syncState.at};updateSync()}});
function refreshFromRemote(){const editing=document.activeElement?.matches('input,textarea,select');if(formDirty||editing){remoteUpdate=true;updateSync();return}navigate()}
async function importQuestions(qs){const batch=qs.filter(q=>!state.questions[q.id]).map((q,i)=>({v:VERSION,id:uid(),device,clock:Math.max(0,...events.map(e=>e.clock))+i+1,at:new Date().toISOString(),type:'question',entity:q.id,data:{...q,reviewStatus:'pending'}}));await putEvents(batch);events=mergeEvents(events,batch);state=reduce(events);channel?.postMessage('saved');if(vault.credentials)vault.sync()}
const features=createFeatures({state:()=>state,events:()=>events,selectedTopic:()=>selectedTopic,refresh:()=>render(),esc,head,field,topicSelect,toast,record,download,toBase64,fromBase64,topicBy,topics,importQuestions});
async function record(type,entity,data,rerender=true){const event={v:VERSION,id:uid(),device,type,entity,data:structuredClone(data),clock:Math.max(0,...events.map(e=>e.clock))+1,at:new Date().toISOString()};await putEvents([event]);events=mergeEvents(events,[event]);state=reduce(events);if(vault.credentials){syncState.kind='pending';syncState.message='Changes pending';clearTimeout(saveTimer);saveTimer=setTimeout(()=>vault.sync(),2500)}channel?.postMessage('saved');if(rerender)render();else updateSync();return event}
function updateSync(){const el=document.querySelector('#syncchip');if(el){el.className=`syncchip ${syncState.kind}`;el.title=syncState.message+(remoteUpdate?' · Updates saved; view refreshes after you leave this form.':'');el.innerHTML=`<span class="dot"></span>${esc(syncState.kind==='error'?'Sync needs attention':syncState.kind==='synced'?'All changes synced':syncState.kind==='syncing'?'Syncing…':syncState.kind==='pending'?`${pendingCount()} pending`:'Device only')}`};const status=document.querySelector('#syncdetail');if(status)status.innerHTML=`<strong>${esc(syncState.message)}</strong><div class="muted">${vault.credentials?`${pendingCount()} unsynced events`:'Unlock on each device to resume across phone and laptop.'}${syncState.at?` · Last sync ${esc(new Date(syncState.at).toLocaleTimeString())}`:''}</div>`}
function navigate(){formDirty=false;remoteUpdate=false;const parts=location.hash.slice(1).split('/');route=parts[0]||'today';if(parts[1])selectedTopic=parts[1];referenceTopic=route==='catalogue'?(parts[1]||''):'';if(route==='learn')step=Number(state.cursor?.topic===selectedTopic?state.cursor.step:0)||0;render()}
function render(){if(!state)return;formDirty=false;const active=route==='learn'?'library':route;const name=state.settings.name||'Aspirant';app.innerHTML=`<div class="shell" data-reading-theme="${state.readingPreferences.theme}" data-focus="${state.readingPreferences.focus}" data-reduce-motion="${state.readingPreferences.motion}" style="--reading-size:${state.readingPreferences.font}px;--reading-spacing:${state.readingPreferences.spacing}"><aside class="sidebar" id="sidebar"><a class="brand" href="#today"><img src="icon.svg" alt=""><div>Group1 Sprint<small>APPSC WORKSPACE</small></div></a><div class="navlabel">YOUR PREPARATION</div><nav aria-label="Main navigation">${routes.map(([r,icon,title])=>`<a class="navlink ${active===r?'active':''}" href="#${r}"><span class="ico" aria-hidden="true">${icon}</span>${title}</a>`).join('')}</nav><div class="sidebarfoot"><span class="weekbadge">Every small step counts</span><div class="spacer"></div><b>Learn. Recall. Repeat.</b>Progress you can pick up anywhere.</div></aside><div class="workspace"><header class="topbar"><button class="app-back" data-action="back" aria-label="Back to previous page" ${route==='today'&&navDepth===0?'disabled':''}>← Back</button><button class="mobilemenu" data-action="menu" aria-label="Toggle navigation">☰</button><div class="crumb">My workspace &nbsp; / &nbsp; <b>${esc(routes.find(r=>r[0]===active)?.[2]||'Study session')}</b></div><div class="topactions"><a href="#settings" class="syncchip" id="syncchip"><span class="dot"></span>Device only</a><span class="date">${dateLabel(today())}</span><div class="avatar" aria-label="${esc(name)}">${esc(name.slice(0,1).toUpperCase())}</div></div></header><main class="main">${comfortControls()}<nav class="btnrow exam-sections" aria-label="Exam sections"><a class="btn secondary" href="#library">APPSC Group-I</a><a class="btn secondary" href="#upsc">UPSC</a><a class="btn secondary" href="#materials">Imported collections</a></nav><div class="membertools"><a href="#${state.cursor?.topic?'learn/'+esc(state.cursor.topic):'library'}">Resume learning →</a><a href="#settings">Backup & restore ↓</a></div>${pages[route]?pages[route]():pages.today()}</main></div><nav class="floating" aria-label="Quick navigation">${routes.filter(r=>['today','library','revisions','practice','insights'].includes(r[0])).map(([r,i,t])=>`<a href="#${r}" class="${active===r?'active':''}"><span class="ico">${i}</span>${r==='library'?'Learn':r==='revisions'?'Review':r==='practice'?'Practice':t}</a>`).join('')}</nav></div>`;updateSync();bind();if(quiz&&!quiz.finished)tick()}
function planDay(){return state.plan?Math.max(1,daysBetween(state.plan.start,today())+1):0}
function dailyTopics(day=planDay()){const gs=topics.filter(t=>t.paper==='I');const science=topics.filter(t=>t.subject==='Science & Technology');return [gs[(Math.max(day,1)-1)%gs.length],science[(Math.max(day,1)-1)%science.length]]}
function topicDone(id){return !!state.topics[id]?.done}
function subjectProgress(){return subjects.map(s=>{const ts=topics.filter(t=>t.subject===s.name);return {name:s.name,done:ts.filter(t=>topicDone(t.id)).length,total:ts.length}})}
function progressRows(){return subjectProgress().map(s=>`<div class="subject"><div class="row between"><span>${s.name}</span><span class="muted">${s.done}/${s.total}</span></div><div class="track"><span style="width:${s.done/s.total*100}%"></span></div></div>`).join('')}


function originalBank(){return practiceBank()}
function adaptiveSet(bank,count,families=false){const history=Object.values(state.attempts).flatMap(a=>a.questions.map((q,i)=>({id:q.id,at:a.ended||a.started||a.deadline,wrong:a.finished&&a.answers[i]?.choice!=null?a.answers[i].choice!==q.answer:undefined})));return chooseCoachedPractice(bank,{exam:practiceScope,count,mistakes:learningReport(appSessions(state.attempts),topics).weakTopics,overdue:revisionQueue(state).map(r=>r.topic),history,uniqueFamilies:true});}
function comfortControls(){const p=state.readingPreferences;return `<details class="comfortcontrols"><summary>Reading comfort · ${p.font}px · ${esc(p.theme)}${p.focus?' · focused':''}</summary><form id="comfortform" class="formgrid"><div class="grid three"><label>Appearance<select name="theme">${['paper','sepia','dark'].map(x=>`<option ${p.theme===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Text size<select name="font">${[16,18,20,22].map(x=>`<option ${p.font===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Line spacing<select name="spacing">${[1.7,1.9,2.1].map(x=>`<option ${p.spacing===x?'selected':''}>${x}</option>`).join('')}</select></label></div><label><input type="checkbox" name="focus" ${p.focus?'checked':''}> Focused reading</label><label><input type="checkbox" name="motion" ${p.motion?'checked':''}> Reduce motion</label><button class="btn" type="submit">Save comfort</button><small>Saved with your progress; included in sync and backup. PDF layout stays fixed.</small></form></details>`}

function curriculumPanel(){return `<section class="card curriculum-progress" aria-label="Six-batch curriculum progress"><div class="eyebrow">Chapters and practice, together</div><h2>Six batches. One syllabus sequence.</h2><p>${curriculumProgress().flatMap(b=>b.topics).filter(t=>t.expanded).length} of 65 topics have the new chapter edition. Each edition covers its listed outline; official-syllabus completeness remains under review.</p>${curriculumProgress().map(b=>`<details><summary>Batch ${b.id} · ${b.topics.length} topics · ${b.topics.filter(t=>t.expanded).length}/${b.topics.length} chapter editions available</summary><p>${esc(b.title)}</p><ul>${b.topics.map(t=>`<li>${link(esc(t.title),'learn/'+t.id)} — ${t.expanded?'Chapter available':'Chapter expansion pending'} · ${t.questions} scored questions</li>`).join('')}</ul></details>`).join('')}</section>`}
function flowPanel(t){const c=learningContent(t.id),f=state.learningFlows[t.id]||{topic:t.id,stage:'learn',segment:0,answers:['','',''],reviewed:false,reflection:''},part=c.segments[Math.min(f.segment,c.segments.length-1)],qs=[...originalBank(),...readyQuestions(state)].filter(q=>q.topic===t.id),tested=Object.values(state.attempts).some(a=>a.finished&&a.questions.every(q=>q.topic===t.id));return `<section class="card learningjourney"><div class="eyebrow">YOUR GUIDED STUDY SESSION · ${esc(c.level)}</div><h2>Learn → Recall → Practise → Revise</h2><div class="flowsteps">${stages.map((s,i)=>`<span class="${f.stage===s?'selected':''}">${i+1}. ${esc(s)}</span>`).join('')}</div><form id="learningflowform" class="formgrid">${c.batch?'<button class="btn secondary" name="intent" value="chapterstart">Read chapter from beginning</button>':''}${f.stage==='learn'?`${c.outline?`<details><summary>Chapter outline · Batch ${c.batch}</summary><ol>${c.outline.map(title=>`<li>${esc(title)}</li>`).join('')}</ol></details>`:''}<p class="muted">Section ${Math.min(f.segment,c.segments.length-1)+1} / ${c.segments.length}</p><h3>${esc(part.teTitle||part.title)}</h3><p class="reading" style="white-space:pre-wrap">${esc(part.te||part.text)}</p><div class="recall">${esc(part.teExample||part.example)}</div><p><strong>Exam distinction:</strong> ${esc(part.trap)}</p><p><strong>Explain it back:</strong> ${esc(part.recall)}</p><details><summary>Read this segment in English</summary><p class="reading" style="white-space:pre-wrap">${esc(part.text)}</p></details><details><summary>Sources for further study</summary>${[[c.source.name,c.source.url],...c.sources].map(([name,url])=>`<p><a href="${esc(url)}" target="_blank" rel="noopener">${esc(name)}</a></p>`).join('')}</details>${c.summary?`<details><summary>Revision summary</summary><ul>${c.summary.map(line=>`<li>${esc(line)}</li>`).join('')}</ul></details>`:''}<p class="muted">${c.level==='Short foundation'?'Short foundation; a full chapter and Telugu translation still need expansion.':c.batch?'Original chapter edition covering the listed outline. Full official-syllabus alignment remains under review.':'Original foundation. Read the concepts before testing.'}</p>${f.segment>0?'<button class="btn secondary" name="intent" value="previous">Previous idea</button>':''}<button class="btn" name="intent" value="advance">${f.segment<c.segments.length-1?'Understood · next idea':'Close notes & try recall'}</button>`:f.stage==='recall'?`<p>Explain from memory before revealing the reference.</p>${c.recall.map((q,i)=>`<label>${esc(q)}<textarea name="answer${i}" maxlength="1500">${esc(f.answers[i])}</textarea></label>`).join('')}<details><summary>Compare with reference after trying</summary>${c.references.map(x=>`<p>${esc(x)}</p>`).join('')}</details><label class="check"><input type="checkbox" name="reviewed" ${f.reviewed?'checked':''}> I checked my explanation and corrected misunderstandings.</label><div class="btnrow"><button class="btn secondary" name="intent" value="save">Save draft</button><button class="btn" name="intent" value="advance">Continue to practice</button></div>`:f.stage==='practice'?`<p>${qs.length?`${qs.length} original topic questions available. Recent exact questions are excluded for three days.`:'Scored questions are still being authored for this topic. Save a self-study reflection below; this creates no quiz score.'}</p>${qs.length?btn('Start topic practice','flowquiz'):''}<label>One trap, source or correction<textarea name="reflection" maxlength="1500">${esc(f.reflection)}</textarea></label><button class="btn" name="intent" value="advance" ${qs.length&&!tested?'disabled':''}>Finish & schedule revision</button>`:`<p>Recall returns on days 1, 4 and 7. This is foundation completion, not full syllabus mastery.</p>${link('Open revision queue','revisions')}<button class="btn secondary" name="intent" value="restart">Recall again now</button>`}</form></section>`}

let importIndex=null,importRequest=0,importIndexLoading=false;let importView={query:'',subject:'',collection:'',limit:20,selected:null,data:null,loading:false,error:'',questionQuery:'',questionLimit:20};
function ensureImportIndex(){if(importIndex||importIndexLoading)return;importIndexLoading=true;fetch('./study-imports.json').then(r=>{if(!r.ok)throw Error('Collection index unavailable');return r.json()}).then(data=>{if(!Array.isArray(data.documents))throw Error('Collection index invalid');importIndex=data;if(route==='materials')render()}).catch(e=>{importView.error=e.message;if(route==='materials')render()}).finally(()=>{importIndexLoading=false})}
const pages={
materials(){ensureImportIndex();return importedMaterialsHTML(importIndex,importView)},
upsc(){return upscLibrary(esc,{query:upscQuery,subject:upscSubject,concept:upscConcept,mode:upscMode,stage:upscStage,limit:upscLimit})},
tutor(){return features.tutor()},
today(){const completed=topics.filter(t=>topicDone(t.id)).length,pct=Math.round(completed/topics.length*100),due=revisionQueue(state),day=planDay(),[gs,science]=dailyTopics(),attempts=Object.values(state.attempts).filter(a=>a.finished),accuracy=attempts.length?Math.round(attempts.reduce((n,a)=>n+score(a.questions,a.answers).accuracy,0)/attempts.length):null;const last=state.cursor&&topicBy(state.cursor.topic);return `${head('Your daily command centre',`Make today count, ${esc(state.settings.name)}.`,state.plan?`Day ${day} of ${state.plan.days} · A focused session, one concept at a time.`:'Start a realistic plan. Learn the concepts, then test your recall.',btn('Save & end session','end',true))}${!state.settings.examDate?`<div class="notice">Your exam date is not set. <a href="#settings">Add it after checking the official notification.</a></div>`:!state.settings.examVerified?`<div class="notice">${dateLabel(state.settings.examDate)} is your provisional target. Verify it against the official notification.</div>`:''}<div class="grid four"><div class="card"><span class="muted">Study units completed</span><div class="metric">${completed}<span class="muted"> / ${topics.length}</span></div>${pill('Starter syllabus map','gray')}</div><div class="card"><span class="muted">Revisions due</span><div class="metric">${due.length}</div>${pill('1 · 4 · 7 day recall',due.length?'amber':'gray')}</div><div class="card"><span class="muted">Practice accuracy</span><div class="metric">${accuracy===null?'—':accuracy+'%'}</div><span class="muted">${attempts.length} completed sessions</span></div><div class="card"><span class="muted">Days to target</span><div class="metric">${state.settings.examDate?Math.max(0,daysBetween(today(),state.settings.examDate)):'—'}</div>${pill(state.settings.examVerified?'Source confirmed':'Target not confirmed','amber')}</div></div><div class="spacer"></div><div class="grid cols"><div class="grid"><section class="card leadcard"><div class="row between"><div><div class="eyebrow">${last?'Pick up where you left off':'Your next small step'}</div><h2>${esc(last?.title||'Build your study rhythm.')}</h2><p class="subtitle">${last?'Your lesson position and notes are saved. Continue at your own pace.':'A plan that makes room for learning, daily practice and revision.'}</p></div><div class="ring" style="--pct:${pct}"><div><strong>${pct}%</strong><small>study map</small></div></div></div><div class="btnrow">${last?link('Resume learning',`learn/${last.id}`):state.plan?link('Start today’s topic',`learn/${gs.id}`):link('Review study plan','plan')}${link('Explore topics','library',true)}</div></section><section class="card"><div class="sectiontop"><h2>Today’s focus</h2>${pill(day&&day%7===0?'Weekly review':'Four focused segments','gray')}</div>${!state.plan?empty('First, approve your plan','Choose your daily hours and confirm the outline.',link('Review plan','plan')):`<div class="task"><div class="taskicon">01</div><div class="tasktext"><h3>${esc(gs.title)}</h3><p class="muted">Static GS · concept, recall & traps</p></div>${link(topicDone(gs.id)?'Review':'Learn',`learn/${gs.id}`,true)}</div><div class="task"><div class="taskicon">02</div><div class="tasktext"><h3>Daily GMA drill</h3><p class="muted">5 original questions · 6 minutes</p></div>${btn('Practise','gma',true)}</div><div class="task"><div class="taskicon">03</div><div class="tasktext"><h3>${day%2===0?'Interleaved revision':esc(science.title)}</h3><p class="muted">Science & Technology · Paper II</p></div>${link('Open',day%2===0?'revisions':`learn/${science.id}`,true)}</div><div class="task"><div class="taskicon">04</div><div class="tasktext"><h3>Connect a current event</h3><p class="muted">Bring a headline · link it to a static topic</p></div>${link('Add','current',true)}</div>${day%7===0?`<div class="notice">Weekly checkpoint: review your ledger and run a timed 30-question test when your question bank is ready.</div>`:''}${day>state.plan.days-12?`<div class="notice">Final stretch: prioritise full mocks, error review and revision. Avoid new low-priority material.</div>`:''}`}</section><section class="card"><div class="sectiontop"><h2>Pending & recall</h2>${link('All revisions','revisions',true)}</div>${due.length?due.slice(0,3).map(r=>`<div class="task"><div class="taskicon">↻</div><div class="tasktext"><h3>${esc(topicBy(r.topic).title)}</h3><p class="muted">Due ${dateLabel(r.due)} · ${r.interval}-day recall</p></div>${link('Review',`learn/${r.topic}`,true)}</div>`).join(''):empty('Your queue is clear','Complete a topic to schedule recall on days 1, 4 and 7.')}${pendingTopics().length?`<details><summary>${pendingTopics().length} unfinished topics from earlier plan days</summary>${pendingTopics().slice(0,10).map(t=>`<div class="task"><div class="tasktext"><h3>${esc(t.title)}</h3></div>${link('Learn',`learn/${t.id}`,true)}</div>`).join('')}</details>`:''}</section></div><div class="grid"><section class="card"><div class="sectiontop"><h2>Your study map</h2>${link('View','library',true)}</div>${progressRows()}<p class="muted small">Completion measures this starter map, not mastery or an official syllabus percentage.</p></section><section class="card"><div class="eyebrow">Memory that lasts</div><h2>Recall beats rereading.</h2><p class="muted">Explain yesterday’s concept without notes. Check it, correct it, then revisit it after a gap.</p>${link('Open recall queue','revisions',true)}</section></div></div>`},
plan(){const gsCount=topics.filter(t=>t.paper==='I').length;return `${head('Before day one','A plan you can sustain.','This is a provisional study map. Verify and expand it against the official syllabus before treating it as complete.') }<div class="grid cols"><section class="card"><h2>Your preparation outline</h2><form id="planform" class="formgrid">${field('Plan start','start','date',state.plan?.start||today(),'required')}${field('Days available','days','number',state.plan?.days||105,'min="21" max="365" required')}${field('Daily study hours','hours','number',state.settings.hours,'min="0.5" max="12" step="0.5" required')}<div class="notice">First learn a small concept. Then recall, attempt MCQs and review mistakes. Daily workload should fit your hours; do not chase completion at the expense of understanding.</div><div class="tablewrap"><table><thead><tr><th>Phase</th><th>Work</th></tr></thead><tbody><tr><td>Foundation</td><td>${gsCount} GS units; alternate science with recall. Daily GMA & headline linking.</td></tr><tr><td>Every 7th day</td><td>30-question mixed test, ledger review, guess/skip analysis.</td></tr><tr><td>Final 12 days</td><td>Full mocks, targeted correction and spaced recall.</td></tr></tbody></table></div><label class="check"><input type="checkbox" required> I approve this provisional outline; adjust it to my capacity.</label><button class="btn" type="submit">Approve & start plan</button></form></section><div class="grid"><section class="card"><h2>Do not miss</h2><ul class="list"><li>Constitution, governance and social justice</li><li>Indian history and Andhra culture</li><li>Economy fundamentals and the current AP survey</li><li>Indian/AP geography and environmental basics</li><li>GMA speed, science and sourced current affairs</li></ul></section><section class="card"><h2>Use your time carefully</h2><p class="muted">Skim obscure lists, isolated dates, speculative predictions, outdated figures and unsourced trivia. This is a study heuristic, not a PYQ-frequency finding.</p><p class="muted">Yield map: <b>pattern not verified</b>. No extra days are assigned from remembered or invented exam years.</p></section></div></div>`},
library(){const list=topics.filter(t=>(!subjectFilter||t.subject===subjectFilter)&&`${t.title} ${t.subject}`.toLowerCase().includes(search.toLowerCase()));return `${head('Study beyond the routine','Your topic library.','Choose a topic, save your notes and resume from any device once synced.',link('Study plan','plan',true))}${curriculumPanel()}<div class="search"><input id="topicsearch" type="search" placeholder="Search concepts, subjects…" aria-label="Search topics" value="${esc(search)}"><select id="subjectfilter" aria-label="Filter subjects"><option value="">All subjects</option>${subjects.map(s=>`<option ${subjectFilter===s.name?'selected':''}>${s.name}</option>`).join('')}</select></div><div class="notice">${topics.length} study units · Batches 1–3 chapters and scored practice now available · Paper allocation follows your supplied blueprint and still needs official syllabus verification. Telugu labels are descriptive, not certified APPSC terminology.</div><div class="grid three">${list.map(t=>`<article class="card topiccard"><div class="row between">${pill(`Paper ${t.paper}`,t.paper==='II'?'blue':'')}${pill(topicDone(t.id)?'Completed':state.notes[t.id]?'Notes saved':'Not started',topicDone(t.id)?'':'gray')}</div><span class="muted">${esc(t.subject)}</span><h3>${esc(t.title)}</h3><div class="te">${esc(t.te)}</div><p class="muted">${esc(topicEdition(t.id))}</p>${link('Open topic',`learn/${t.id}`,true)}</article>`).join('')||empty('No matching topics','Try another keyword or subject.')}</div>`},

catalogue(){const ms=(referenceIndex?.microtopics||[]).filter(m=>(!referenceTopic||m.topic===referenceTopic)&&[m.title,m.section].join(' ').toLowerCase().includes(search.toLowerCase()));return `${head('Learn inside your workspace','Explore related concepts.','Choose a study unit for its foundation, examples and recall.') }<div class="field"><label for="topicsearch">Find a concept</label><input id="topicsearch" value="${esc(search)}"></div>${referenceTopic?link('Browse all concepts','catalogue',true):''}<div class="grid two">${ms.slice(0,referenceLimit).map(m=>`<article class="card"><h3>${esc(m.title)}</h3><p>${esc(m.section)}</p>${m.topic?link('Read the related lesson','learn/'+m.topic,true):pill('Topic placement being checked','amber')}</article>`).join('')}</div>${ms.length>referenceLimit?btn('Show 20 more','referencesmore',true):''}${!referenceIndex?empty('Loading concepts',referenceError||'Preparing the concept map…'):''}`},
learn(){const t=topicBy(selectedTopic),guided=t.id===rights.id&&!learningContent(t.id).batch,note=state.notes[t.id]||{},stage=lesson.steps[Math.min(step,3)];return `${head(`${esc(t.subject)} · Paper ${esc(t.paper)}`,esc(t.title),'Understand one idea. Recall it. Then test it.',btn('Copy tutor prompt','prompt',true))}${link('Related micro-topics & references','catalogue/'+t.id,true)}${flowPanel(t)}${upscTopicLinks(t.id)}<div class="grid lessonlayout"><aside class="card lessonsteps">${guided?lesson.steps.map((s,i)=>`<button class="step ${step===i?'active':''}" data-action="step" data-step="${i}">${i+1}. ${s.heading}</button>`).join(''):`<div><div class="eyebrow">Study workflow</div><p>01 · Read a trusted source</p><p>02 · Explain it from memory</p><p>03 · Check your mistakes</p><p>04 · Schedule recall</p>${pill(topicDone(t.id)?'Completed':'In progress','gray')}</div>`}</aside><div class="grid"><section class="card">${guided?`<div class="sectiontop"><span class="eyebrow">Concept ${step+1} / 4</span>${pill('Original teaching material','gray')}</div><h2>${stage.heading}</h2><p class="reading">${esc(stage.text)}</p><div class="recall"><h3>Pause & recall</h3><p class="no-margin">${stage.recall}</p></div><p class="muted small">Exact article numbers: VERIFY against the <a href="${lesson.source}" target="_blank" rel="noopener">official Constitution</a>. PYQ alert: theme only, years unknown.</p><div class="btnrow">${step?btn('Previous','prevstep',true):''}${step<3?btn('Save & next segment','nextstep'):btn('Try 2 original MCQs','rightsquiz')}${btn(topicDone(t.id)?'Mark incomplete':'Mark concept learned','complete',true)}</div>`:`<h2>${learningContent(t.id).batch?'Make the chapter your own':'Build your source-backed notes'}</h2><p class="reading">${learningContent(t.id).batch?'Read the chapter above, try its recall prompts and scored practice, then save your examples or corrections here.':'Read the foundation guide below, add source-backed notes and explain it in your own words.'}</p><div class="recall"><h3>Your recall check</h3><p class="no-margin">Explain this concept without notes. What would confuse you in an MCQ? Add that trap to your mistake ledger.</p></div><div class="btnrow">${btn('Copy tutor prompt','prompt')}${btn(topicDone(t.id)?'Mark incomplete':'Mark concept learned','complete',true)}</div>`}</section>${guided||learningContent(t.id).batch?'':features.foundation(t.id)}<section class="card"><h2>Your notebook</h2><form id="noteform" class="formgrid"><div class="field"><label for="notes">Concept, examples & traps</label><textarea id="notes" name="text" placeholder="Write the concept in your own words. Notes save when you press Save." required>${esc(note.text||'')}</textarea></div>${field('Source URL (optional)','source','url',note.source||'')}<button type="submit" class="btn">Save notes</button></form><div class="btnrow">${link('Log a mistake','ledger',true)}${link('Find related papers','papers',true)}</div></section></div></div>`},
revisions(){const due=revisionQueue(state),future=Object.entries(state.topics).flatMap(([id,t])=>t.done&&t.day?[1,4,7].map(n=>({topic:id,due:addDays(t.day,n),id:`${id}:${t.day}:${n}`})):[]).filter(r=>r.due>today()&&!state.revisions[r.id]);return `${head('Build lasting recall','Return before you forget.','Recall from memory first. Open your notes only after you have tried.') }<div class="grid four"><div class="card"><span class="muted">Due now</span><div class="metric">${due.length}</div></div><div class="card"><span class="muted">Upcoming</span><div class="metric">${future.length}</div></div><div class="card"><span class="muted">Reviewed</span><div class="metric">${Object.keys(state.revisions).length}</div></div><div class="card"><span class="muted">Recall schedule</span><div class="metric">1 · 4 · 7</div></div></div><div class="spacer"></div><section class="card"><h2>Today’s recall queue</h2>${due.length?due.map(r=>`<div class="task"><div class="taskicon">${r.interval}</div><div class="tasktext"><h3>${esc(topicBy(r.topic).title)}</h3><p class="muted">Due ${dateLabel(r.due)} · Explain the idea and one trap without notes.</p></div><div class="btnrow no-margin">${link('Notes',`learn/${r.topic}`,true)}${btn('Recall done','review',false,`data-id="${esc(r.id)}" data-topic="${r.topic}"`)}</div></div>`).join(''):empty('No recall due yet','When you mark a concept learned, three revisions are scheduled automatically.')}</section><div class="spacer"></div><section class="card"><h2>Coming up</h2>${future.length?future.sort((a,b)=>a.due.localeCompare(b.due)).slice(0,10).map(r=>`<div class="task"><div class="tasktext"><h3>${esc(topicBy(r.topic).title)}</h3><p class="muted">${dateLabel(r.due)}</p></div>${pill('Scheduled','gray')}</div>`).join(''):empty('Nothing scheduled','Complete your first concept to get started.')}</section>`},
practice(){if(quiz)return renderQuiz();const bank=readyQuestions(state),attempts=Object.values(state.attempts).filter(a=>a.finished);return `<label>Practice scope<select id="practice-scope">${['APPSC Group-I','UPSC','Other PSC'].map(x=>`<option ${x===practiceScope?'selected':''}>${x}</option>`).join('')}</select></label><p>Source-checked common questions are included. Scores are learning scores; exam patterns differ.</p>${head('Accuracy before attempts','Train for a safer score.','Imported material stays in review until you check its topic, answer and sources.') }<section class="card"><div class="eyebrow">YOUR NEXT USEFUL QUESTIONS</div><h2>Personalised practice</h2><p>Mistakes and overdue revision receive more weight. Recent exact repeats are avoided when eligible alternatives exist. Includes reviewed original variations.</p>${btn('Start up to 10 questions','adaptive')}</section><div class="spacer"></div><div class="grid three"><section class="card"><div class="eyebrow">Daily speed drill</div><h2>General Mental Ability</h2><p class="muted">5 original starter questions · 6 minutes. Repeat the starter set or import fresh questions.</p>${btn('Start GMA drill','gma')}</section><section class="card"><div class="eyebrow">Weekly checkpoint</div><h2>Mixed practice</h2><p class="muted">30 questions · 30 minutes. Drawn from your imported bank, without repeats.</p>${btn('Start weekly test','weekly',false,bank.length<30?'disabled':'')}<p class="muted small">${bank.length}/30 questions available</p></section><section class="card"><div class="eyebrow">Exam simulation</div><h2>Full paper mock</h2><p class="muted">120 questions · 120 minutes. Pick Paper I or II before starting.</p><select id="mockpaper" aria-label="Mock paper"><option value="I">Paper I</option><option value="II">Paper II</option></select><div class="btnrow">${btn('Start full mock','mock')}</div></section></div><div class="spacer"></div><div class="notice">Practice scoring uses +1 correct, −⅓ wrong, 0 skipped; verify the actual exam rule. Eliminating two options is a useful caution rule, not a mathematical guarantee. Track confidence and learn from the outcomes.</div>${renderBankReview()}<section class="card"><div class="sectiontop"><h2>Your question bank</h2>${pill(`${bank.length} imported`,'gray')}</div><form id="bankform" class="formgrid"><div class="field"><label for="bankfile">Import JSON or CSV questions</label><input type="file" id="bankfile" accept=".json,.csv" required></div><label class="check"><input type="checkbox" required> I understand imported questions enter the review queue before tests.</label><button class="btn" type="submit">Validate & import</button></form><details><summary>Import format & source rules</summary><p class="small">JSON: an array of objects. CSV columns: id,text,A,B,C,D,answer,topic,kind,year,source,paper,questionNumber,explanation. answer is a zero-based index (0–3). kind is original, practice or PYQ. Every import enters review. Unassigned topics stay visible here. PYQs need year, paper, question number and an HTTPS source; approval also requires APPSC paper and key URLs. Your review is recorded; the app does not authenticate documents.</p><pre class="codebox">${esc(JSON.stringify([{id:'my-question-1',text:'What is 25% of 80?',options:['10','15','20','25'],answer:2,topic:'t-4-1',kind:'original',paper:'II',explanation:'80 × 0.25 = 20.'}],null,2))}</pre></details></section><div class="spacer"></div><section class="card"><h2>Recent sessions</h2>${attempts.length?`<div class="tablewrap"><table><thead><tr><th>Session</th><th>Net score</th><th>Accuracy</th><th>Time</th></tr></thead><tbody>${attempts.slice(-8).reverse().map(a=>{const s=score(a.questions,a.answers);return `<tr><td>${esc(a.label)}</td><td>${s.net.toFixed(2)} / ${a.questions.length}</td><td>${s.accuracy.toFixed(0)}%</td><td>${Math.round((a.ended-a.started)/1000)} sec</td></tr>`}).join('')}</tbody></table></div>`:empty('No sessions yet','Your score, answers and guess/skip decisions will appear here.')}</section>`},
ledger(){const ms=Object.entries(state.mistakes);return `${head('Turn errors into understanding','Your mistake ledger.','Capture the cause, write the correction, then re-test the concept.') }<div class="grid cols"><section class="card"><h2>Log a learning moment</h2><form id="mistakeform" class="formgrid">${topicSelect()}<div class="field"><label for="errortype">Error type</label><select id="errortype" name="type"><option>Knowledge</option><option>Confusion</option><option>Careless</option><option>Time</option></select></div>${field('What went wrong?','error','text','','required maxlength="1000"')}${field('The correct idea or action','correction','text','','required maxlength="2000"')}<button class="btn" type="submit">Save mistake</button></form></section><section class="card"><h2>Review every 7 days</h2><p class="muted">Explain the correction without notes, then try a fresh question. Mark reviewed only after that check.</p>${ms.length?ms.slice(-10).reverse().map(([id,m])=>`<div class="journal">${pill(esc(m.type),'amber')}<h3>${esc(topicBy(m.topic).title)}</h3><p class="small">${esc(m.error)}</p><p class="muted"><b>Correction:</b> ${esc(m.correction)}</p>${btn('Mark reviewed','mistakereview',true,`data-id="${esc(id)}"`)}<span class="muted block">${m.reviewed?`Reviewed ${dateLabel(m.reviewed)}`:`Next review ${dateLabel(addDays(m.day,7))}`}</span></div>`).join(''):empty('Your ledger is empty','Mistakes are useful evidence. Add the first one when it happens.')}</section></div>`},
papers(){return `${head('Your source of truth','The paper vault.','Keep question papers, official keys and reference PDFs together. Nothing here is auto-labelled as a verified PYQ.') }<div class="grid cols"><section class="card"><h2>Add a paper or answer key</h2><form id="paperform" class="formgrid">${field('Title','title','text','','required maxlength="200"')}${topicSelect()}${field('Source URL','source','url','','required')}${field('Exam year (optional)','year','number','','min="1900" max="2100"')}<div class="field"><label for="paperstage">Paper stage</label><select id="paperstage" name="stage"><option value="reference">Reference / stage not checked</option><option value="prelims">APPSC Group-I Prelims</option><option value="mains">Mains / language paper</option></select></div><div class="field"><label for="paperid">Paper</label><select id="paperid" name="paper"><option value="I">I</option><option value="II">II</option></select></div><div class="field"><label for="paperfile">PDF or image · up to 4 MB</label><input type="file" id="paperfile" accept="application/pdf,image/png,image/jpeg" required></div><button type="submit" class="btn">Save & extract PDF</button></form>${features.paperTools()}<p class="muted small">Files stay on this device and are included in backups. When sync is unlocked, they upload as encrypted vault records; large files take longer.</p></section><section class="card"><div class="sectiontop"><h2>Saved references</h2>${pill(`${Object.keys(state.papers).length} files`,'gray')}</div>${Object.entries(state.papers).map(([id,p])=>`<div class="task"><div class="taskicon">▧</div><div class="tasktext"><h3>${esc(p.title)}</h3><p class="muted">${esc(p.year||'Year not set')} · ${esc(topicBy(p.topic).title)}</p><a class="small" href="${safeURL(p.source)}" rel="noopener" target="_blank">Source</a></div>${btn('Open file','paperopen',true,`data-id="${esc(id)}"`)}${p.mime==='application/pdf'?`<div class="btnrow paperactions">${btn('Extract','paperextract',true,`data-id="${esc(id)}"`)}${btn('OCR scan','paperocr',true,`data-id="${esc(id)}"`)}${btn('Review text','papertext',true,`data-id="${esc(id)}"`)}</div>`:''}</div>`).join('')||empty('No papers saved','Add an official paper and key. PDF text is extracted locally; objective questions enter review with unknown answers.')}</section></div>`},
current(){const hs=Object.values(state.headlines);return `${head('Connect static and current','A headline with a purpose.','Bring a sourced AP, national or international headline. Save why it matters to your syllabus.') }${features.news()}<div class="grid cols"><section class="card"><form id="headlineform" class="formgrid">${field('Headline','title','text','','required maxlength="500"')}${field('Event date','day','date',today(),'required')}${topicSelect()}${field('Source URL','source','url','','required')}<div class="field"><label for="connection">How does it connect to the topic?</label><textarea id="connection" name="connection" required placeholder="The policy, concept, AP angle or possible examiner trap."></textarea></div><button type="submit" class="btn">Save headline</button></form></section><section class="card"><h2>Your current affairs journal</h2>${hs.length?hs.slice(-15).reverse().map(h=>`<article class="journal"><span class="muted">${dateLabel(h.day)} · ${esc(topicBy(h.topic).title)}</span><h3>${esc(h.title)}</h3><p class="muted">${esc(h.connection)}</p><a class="small" href="${safeURL(h.source)}" rel="noopener" target="_blank">Read source</a></article>`).join(''):empty('No headlines recorded','This journal uses headlines you provide. It does not fabricate or automatically fetch news.')}</section></div>`},
insights(){const finished=Object.values(state.attempts).filter(a=>a.finished),done=topics.filter(t=>topicDone(t.id)),errors=Object.values(state.mistakes),weak=Object.entries(errors.reduce((a,m)=>(a[m.topic]=(a[m.topic]||0)+1,a),{})).sort((a,b)=>b[1]-a[1]).slice(0,5);return `${trackerHTML(learningReport(appSessions(state.attempts),topics))}${head('Evidence, not guesswork','See what is improving.','Completion, practice and errors each tell a different part of the story.') }<div class="grid four"><div class="card"><span class="muted">Concepts learned</span><div class="metric">${done.length}</div></div><div class="card"><span class="muted">Completed tests</span><div class="metric">${finished.length}</div></div><div class="card"><span class="muted">Recorded mistakes</span><div class="metric">${errors.length}</div></div><div class="card"><span class="muted">Revisions completed</span><div class="metric">${Object.keys(state.revisions).length}</div></div></div><div class="spacer"></div><div class="grid two"><section class="card"><h2>Accuracy over your last sessions</h2>${finished.length?`<div class="chart" role="img" aria-label="Practice accuracy by session">${finished.slice(-8).map((a,i)=>{const s=score(a.questions,a.answers);return `<div class="barcol"><span class="muted">${Math.round(s.accuracy)}%</span><div class="bar" style="height:${Math.max(2,s.accuracy)}%"></div><small>${i+1}</small></div>`}).join('')}</div><p class="muted">Accuracy = correct ÷ attempted. See Practice for scores and skipped answers.</p>`:empty('Your first score starts the trend','Take a drill. We do not show illustrative scores as your progress.')}</section><section class="card"><h2>Topics needing attention</h2>${weak.length?weak.map(([id,count])=>`<div class="task"><div class="tasktext"><h3>${esc(topicBy(id).title)}</h3><p class="muted">${count} recorded errors</p></div>${link('Revisit',`learn/${id}`,true)}</div>`).join(''):empty('No weak topics identified yet','Your ledger provides the evidence for these recommendations.')}</section><section class="card"><h2>Coverage of your study map</h2>${progressRows()}</section><section class="card"><h2>Latest learning activity</h2>${events.filter(e=>['topic','revision','attempt','note'].includes(e.type)).slice(-8).reverse().map(e=>`<div class="task"><div class="tasktext"><h3>${esc(e.type==='attempt'?e.data.label:topicBy(e.type==='revision'?e.data.topic:e.entity).title)}</h3><p class="muted">${esc(e.type)} saved · ${esc(new Date(e.at).toLocaleString('en-IN'))}</p></div></div>`).join('')||empty('Ready for your first session','Your real activity will appear here.')}</section></div>`},
settings(){return `${head('Your workspace, your control','Settings & device sync.','Use the same private repository and vault passphrase on phone and laptop.') }<div class="grid cols"><div class="grid">${features.settings()}<section class="card"><h2>Your study profile</h2><form id="profileform" class="formgrid">${field('Display name','name','text',state.settings.name,'required maxlength="80"')}${field('Daily study hours','hours','number',state.settings.hours,'required min="0.5" max="12" step="0.5"')}<div class="field"><label for="language">Tutor prompt language</label><select id="language" name="language">${['English','Telugu','English + Telugu'].map(l=>`<option ${l===state.settings.language?'selected':''}>${l}</option>`).join('')}</select></div>${field('Target exam date (leave blank until confirmed)','examDate','date',state.settings.examDate)}${field('Official notification URL','examSource','url',state.settings.examSource||'')}<label class="check"><input id="examVerified" name="examVerified" type="checkbox" ${state.settings.examVerified?'checked':''}> I checked this date in the official notification.</label><button type="submit" class="btn">Save profile</button></form></section><section class="card"><h2>Connect your private vault</h2><div id="syncdetail" class="statusbox"></div><div class="spacer"></div><form id="syncform" class="formgrid">${field('Private data repository','repo','text','imranshaik-pro/crack-group1-data','required autocomplete="off"')}${field('Fine-grained GitHub token','token','password','','required autocomplete="off"')}${field('Shared vault passphrase','passphrase','password','','required minlength="12" autocomplete="off"')}<p class="muted small">Limit the token to this private repository, with Contents read/write. Token and passphrase stay in memory until the page closes or you lock sync. Use the same passphrase on every device. Losing it prevents recovery of encrypted remote records.</p><button class="btn" type="submit">Unlock & sync</button></form><div class="btnrow">${btn('Sync now','sync',true)}${btn('Lock sync','lock',true)}</div></section></div><div class="grid"><section class="card"><h2>Keep a recovery copy</h2><p class="muted">Export all study events, attachments and notes. Credentials are excluded. The JSON file contains personal data in readable form; keep it private.</p>${btn('Export full backup','export')}<div class="spacer"></div><form id="importform" class="formgrid"><div class="field"><label for="backupfile">Restore / merge backup</label><input id="backupfile" type="file" accept=".json" required></div><button type="submit" class="btn secondary">Validate & merge</button></form></section><section class="card"><h2>How to switch devices</h2><ol class="list"><li>Unlock sync on the current device.</li><li>Select “Save & end session”; wait for “All changes synced”.</li><li>Open the app on your other device and unlock the same vault.</li><li>Sync before resuming. Offline work uploads when you reconnect and unlock.</li></ol><p class="muted">If sync fails, continue locally or export a backup. Never clear browser storage before saving your work elsewhere.</p></section><section class="card"><h2>Install on Android</h2><p class="muted">Open the hosted app in Chrome, then use its menu to install or add it to your home screen. Open it online once to cache the app. HTTPS is required for offline installation.</p><a href="https://portal-psc.ap.gov.in/" target="_blank" rel="noopener">Official APPSC portal</a><p class="muted small">No notification number, vacancy count or exam schedule is assumed verified by this app.</p></section></div></div>`}
};
function pendingTopics(){if(!state.plan)return [];const found=new Map();for(let i=1;i<Math.min(planDay(),state.plan.days-12);i++){const [a,b]=dailyTopics(i);if(!topicDone(a.id))found.set(a.id,a);if(i%2&&!topicDone(b.id))found.set(b.id,b)}return [...found.values()]}
function renderBankReview(){const all=Object.values(state.questions),pending=all.filter(q=>!['reviewed','rejected'].includes(q.reviewStatus)),q=pending[0];return `<section class="card"><div class="sectiontop"><div><div class="eyebrow">Content quality desk</div><h2>Review imported material</h2></div>${pill(`${pending.length} awaiting review`,'amber')}</div><p class="muted">${readyQuestions(state).length} eligible for tests · ${all.filter(q=>q.reviewStatus==='rejected').length} excluded. Check every answer before trusting your score. Source claims and recent events remain unverified until you inspect them.</p>${q?`<details open><summary>Next: ${esc(q.origin?.bank||q.id)}</summary><p class="muted small">${esc(q.origin?.repo||'User import')} · ${esc(q.origin?.mappingReason||'Check the suggested topic.')} ${esc((q.reviewFlags||[]).join(' · '))}</p><form id="reviewquestion" class="formgrid"><input type="hidden" name="id" value="${esc(q.id)}"><div class="field"><label>Question<textarea name="text" required>${esc(q.text)}</textarea></label></div>${q.options.map((o,i)=>field(`Option ${'ABCD'[i]}`,'ABCD'[i],'text',o,'required')).join('')}<div class="field"><label>Answer index<select name="answer" required>${q.answerUnknown?'<option value="" selected>Unknown — check the answer key</option>':''}${q.options.map((_,i)=>`<option value="${i}" ${!q.answerUnknown&&i===q.answer?'selected':''}>${'ABCD'[i]}</option>`).join('')}</select></label></div><div class="field"><label>Explanation<textarea name="explanation" required>${esc(q.explanation)}</textarea></label></div><div class="field"><label>Study topic<select name="topic"><option value="">Unassigned — choose a unit</option>${topics.map(t=>`<option value="${t.id}" ${q.topic===t.id?'selected':''}>${esc(t.subject+' · '+t.title)}</option>`).join('')}</select></label></div>${field('Source URL (paper for PYQ)','source','url',q.source||'')}${field('Official answer key URL (required for PYQ)','answerKeySource','url',q.answerKeySource||'')}<div class="field"><label>Review record<textarea name="reviewNote" placeholder="Book/page or official URL; what did you check or correct?">${esc(q.reviewNote||'')}</textarea></label></div><div class="notice">Approve only APPSC Group-I Prelims material after checking the question, answer and topic. Keep Mains/language papers and TGPSC references in the paper library. Approval records your review, not independent verification.</div><div class="btnrow"><button class="btn" name="decision" value="approve">Save review & enable practice</button><button class="btn secondary" name="decision" value="reject" formnovalidate>Exclude from tests</button><button class="btn secondary" type="button" data-action="auditquestion" data-id="${esc(q.id)}">Ask tutor to audit</button></div></form></details>`:empty('No material awaiting review','Import a question pack below to start checking it.')}</section><div class="spacer"></div>`}
function renderQuiz(){const a=quiz;if(a.finished){const s=score(a.questions,a.answers),guesses=a.answers.filter(x=>x?.confidence==='Guess').length;return `${head('Session review',`${s.net.toFixed(2)} / ${a.questions.length}`,`${s.correct} correct · ${s.wrong} wrong · ${s.skipped} skipped`,btn('Back to practice','closequiz',true))}<div class="grid three"><div class="card"><span class="muted">Accuracy</span><div class="metric">${s.accuracy.toFixed(0)}%</div></div><div class="card"><span class="muted">Time used</span><div class="metric">${Math.round((a.ended-a.started)/1000)}s</div></div><div class="card"><span class="muted">Guessed attempts</span><div class="metric">${guesses}</div></div></div><div class="spacer"></div><section class="card"><h2>Learn from every option</h2>${a.questions.map((q,i)=>{const choice=a.answers[i]?.choice,correct=choice===q.answer;return `<div class="result ${choice!==null&&choice!==undefined&&!correct?'wrong':''}"><h3>${i+1}. ${esc(q.text)}</h3><p class="small">Your answer: ${choice==null?'Skipped':esc(q.options[choice])} · Correct: ${esc(q.options[q.answer])}</p><p class="muted">${esc(q.explanation)}</p><p class="muted small">Confidence: ${esc(a.answers[i]?.confidence||'Skipped')} · Eliminated: ${a.answers[i]?.eliminated||0}</p>${!correct?btn('Add correction to ledger','quizmistake',true,`data-index="${i}"`):''}</div>`}).join('')}<p class="muted">The negative mark is a practice setting. Judge your elimination strategy from actual outcomes, not confidence alone.</p></section>`}const i=a.index,q=a.questions[i],ans=a.answers[i]||{},count=a.answers.filter(x=>x?.choice!=null).length;return `${head(a.label,'One question at a time.',`${count} answered · ${a.questions.length} total · progress saves after each decision`,pill(q.kind==='PYQ'?`User-reviewed PYQ · ${q.year}`:q.kind==='practice'?'Imported practice · user reviewed':'Original practice','gray'))}<div class="grid cols"><section class="card"><div class="sectiontop"><span class="muted">Question ${i+1} of ${a.questions.length}</span><span id="quiztimer" class="timer" aria-label="Time remaining">--:--</span></div><div class="track"><span style="width:${(i+1)/a.questions.length*100}%"></span></div><div class="spacer"></div><p class="muted small">${esc(q.selectionReason||'Exam simulation / foundation exercise')}${q.parentId?' · Original variation · '+esc(q.format):''}</p><h2>${esc(q.text)}</h2>${q.options.map((o,j)=>`<button class="option ${ans.choice===j?'selected':''}" data-action="answer" data-choice="${j}"><span class="letter">${'ABCD'[j]}</span>${esc(o)}</button>`).join('')}<div class="grid two"><div class="field"><label for="confidence">How sure are you?</label><select id="confidence">${['Confident','Eliminated','Guess'].map(c=>`<option ${ans.confidence===c?'selected':''}>${c}</option>`).join('')}</select></div><div class="field"><label for="eliminated">Options eliminated</label><select id="eliminated">${[0,1,2,3].map(n=>`<option ${Number(ans.eliminated||0)===n?'selected':''}>${n}</option>`).join('')}</select></div></div><div class="btnrow">${i?btn('Previous','quizprev',true):''}${btn('Skip','skip',true)}${i<a.questions.length-1?btn('Next question','quiznext'):btn('Submit test','submitquiz')}</div></section><aside class="card"><h2>Attempt with intent</h2><p class="muted">Read every option. Distinguish recall from a guess. If you are unsure, skipping preserves time and avoids a negative mark.</p><p class="muted">Eliminating two options can improve your odds, but elimination must be reliable. We record your decision so you can check it later.</p>${q.kind==='PYQ'?`<p class="muted small">Paper ${esc(q.paper)} · Q ${esc(q.questionNumber)}. <a href="${safeURL(q.source)}" target="_blank" rel="noopener">Check supplied source</a></p>`:''}${btn('Submit early','submitquiz',true)}<p class="muted small">Timer continues if you leave the page. An unfinished test resumes from its saved position.</p></aside></div>`}
async function startQuiz(label,questions,seconds){const active=Object.values(state.attempts).find(a=>!a.finished);if(active){quiz=structuredClone(active);location.hash='practice';render();toast('Resuming your unfinished test.');return}if(!questions.length)throw Error('No fresh questions remain. Try another topic or return after three days.');quiz={id:uid(),label,questions,answers:questions.map(()=>({choice:null,confidence:'Confident',eliminated:0})),index:0,started:Date.now(),deadline:Date.now()+seconds*1000,finished:false};await record('attempt',quiz.id,quiz,false);location.hash='practice';render();clearInterval(timerHandle);timerHandle=setInterval(tick,1000)}
function tick(){if(!quiz||quiz.finished)return;const left=Math.max(0,Math.ceil((quiz.deadline-Date.now())/1000));const el=document.querySelector('#quiztimer');if(el)el.textContent=`${String(Math.floor(left/60)).padStart(2,'0')}:${String(left%60).padStart(2,'0')}`;if(!left)finishQuiz(true)}
let finishing=false;async function finishQuiz(expired=false){if(finishing||!quiz||quiz.finished)return;finishing=true;try{quiz.finished=true;quiz.ended=expired?quiz.deadline:Date.now();await record('attempt',quiz.id,quiz);clearInterval(timerHandle);if(expired)toast('Time is up. Your saved answers have been scored.')}finally{finishing=false}}
async function quizSave(){await record('attempt',quiz.id,structuredClone(quiz),false)}
function bind(){document.querySelectorAll('[data-reviewed-topic]').forEach(el=>el.addEventListener('click',async()=>{const qs=adaptiveSet(originalBank().filter(q=>q.topic===el.dataset.reviewedTopic),10);if(qs.length)await startQuiz(topicBy(el.dataset.reviewedTopic).title,qs,qs.length*60);else toast('No fresh reviewed questions in this scope.')}));document.querySelectorAll('[data-coach-topic]').forEach(el=>el.addEventListener('click',async()=>{const qs=adaptiveSet(originalBank().filter(q=>q.topic===el.dataset.coachTopic),10);if(!qs.length){toast('No fresh reviewed questions in this scope.');return;}await startQuiz(topicBy(el.dataset.coachTopic).title+' · coached practice',qs,qs.length*60)}));document.querySelector('#practice-scope')?.addEventListener('change',e=>{practiceScope=e.target.value;render()});for(const [id,key] of [['importsearch','query'],['importsubject','subject'],['importcollection','collection'],['importquestionsearch','questionQuery']])document.querySelector('#'+id)?.addEventListener(id.includes('search')?'input':'change',e=>{const pos=e.target.selectionStart;importView={...importView,[key]:e.target.value,limit:20,questionLimit:20};render();const el=document.querySelector('#'+id);el?.focus();if(pos!==undefined&&pos!==null)el.setSelectionRange(pos,pos)});document.querySelectorAll('[data-import-action]').forEach(el=>el.addEventListener('click',()=>handleImport(el.dataset))); document.querySelector('#upscconcept')?.addEventListener('change',e=>{upscConcept=e.target.value;upscLimit=20;render()});document.querySelector('#upscstage')?.addEventListener('change',e=>{upscStage=e.target.value;upscLimit=20;render()});document.querySelector('#upscsearch')?.addEventListener('input',e=>{upscQuery=e.target.value;upscLimit=20;const pos=e.target.selectionStart;render();const input=document.querySelector('#upscsearch');input.focus();input.setSelectionRange(pos,pos)});document.querySelector('#upscsubject')?.addEventListener('change',e=>{upscSubject=e.target.value;upscConcept='';upscLimit=20;render()});document.querySelectorAll('form').forEach(f=>f.addEventListener('input',()=>{formDirty=true}));document.querySelectorAll('[data-action]').forEach(el=>el.addEventListener('click',()=>handle(el.dataset).catch(e=>toast(e.message))));document.querySelectorAll('form').forEach(f=>f.addEventListener('submit',e=>{e.preventDefault();formSubmit(f,e.submitter).catch(e=>toast(e.message))}));const searchEl=document.querySelector('#topicsearch');if(searchEl)searchEl.addEventListener('input',e=>{search=e.target.value;const pos=e.target.selectionStart;render();const input=document.querySelector('#topicsearch');input.focus();input.setSelectionRange(pos,pos)});document.querySelector('#subjectfilter')?.addEventListener('change',e=>{subjectFilter=e.target.value;render()});for(const n of ['confidence','eliminated'])document.querySelector('#'+n)?.addEventListener('change',async e=>{quiz.answers[quiz.index][n]=n==='eliminated'?Number(e.target.value):e.target.value;try{await quizSave()}catch(err){toast(err.message)}})}
async function handle(d){if(await features.handle(d))return;switch(d.action){case'upscmode':upscMode=d.mode;upscLimit=20;render();break;case'upscmore':upscLimit+=20;render();break;case'referencesmore':referenceLimit+=20;render();break;case'adaptive':{const qs=adaptiveSet([...originalBank(),...readyQuestions(state)],10);await startQuiz('Personalised practice',qs,qs.length*60);break}case'flowquiz':{const qs=adaptiveSet([...originalBank(),...readyQuestions(state)].filter(q=>q.topic===selectedTopic),10);if(!qs.length)throw Error('No fresh topic questions remain in the three-day window. Try recall or another topic.');await startQuiz(topicBy(selectedTopic).title+' · topic practice',qs.slice(0,10),Math.min(qs.length,10)*60);break}case'back':if(navDepth>0)history.back();else location.hash=route==='learn'?'library':'today';break;case'menu':document.querySelector('#sidebar').classList.toggle('open');break;case'end':await record('session',uid(),{day:today(),ended:Date.now()},false);if(await vault.flush())toast('All changes synced. You can continue on another device.');else toast('Session saved locally. Unlock sync and retry before switching devices.');break;case'prompt':{const prompt=promptFor(topicBy(selectedTopic),state,events);try{await navigator.clipboard.writeText(prompt);toast('Tutor prompt copied, with your saved notes and mistakes.')}catch{download('group1-tutor-prompt.txt',prompt,'text/plain');toast('Prompt downloaded.')}break}case'step':step=Number(d.step);await record('cursor','current',{topic:selectedTopic,step,stage:lesson.steps[step].heading});break;case'nextstep':step=Math.min(3,step+1);await record('cursor','current',{topic:selectedTopic,step,stage:lesson.steps[step].heading});break;case'prevstep':step=Math.max(0,step-1);await record('cursor','current',{topic:selectedTopic,step,stage:lesson.steps[step].heading});break;case'complete':await record('topic',selectedTopic,{done:!topicDone(selectedTopic),day:today()});toast(topicDone(selectedTopic)?'Concept learned. Recall scheduled for days 1, 4 and 7.':'Marked incomplete.');break;case'review':await record('revision',d.id,{topic:d.topic,day:today()});toast('Recall saved. Log any uncertainty in your mistake ledger.');break;case'mistakereview':await record('mistake-review',d.id,{day:today()});break;case'gma':{const qs=adaptiveSet([...originalBank(),...readyQuestions(state)].filter(q=>q.topic.startsWith('t-4-')),5,true);await startQuiz('GMA speed drill',qs,360);break}case'rightsquiz':{const qs=adaptiveSet(originalBank().filter(q=>q.topic===rights.id),5);await startQuiz('Fundamental Rights · original exercises',qs,qs.length*60)};break;case'weekly':await startQuiz('Weekly mixed test',adaptiveSet(readyQuestions(state),30),1800);break;case'mock':{const paper=document.querySelector('#mockpaper').value;const qs=readyQuestions(state).filter(q=>q.paper===paper);if(qs.length<120)throw Error(`Import at least 120 Paper ${paper} questions first; ${qs.length} available.`);await startQuiz(`Paper ${paper} full mock`,shuffle(qs).slice(0,120),7200);break}case'answer':quiz.answers[quiz.index].choice=Number(d.choice);await quizSave();render();break;case'skip':quiz.answers[quiz.index].choice=null;if(quiz.index<quiz.questions.length-1)quiz.index++;await quizSave();render();break;case'quiznext':quiz.index=Math.min(quiz.questions.length-1,quiz.index+1);await quizSave();render();break;case'quizprev':quiz.index=Math.max(0,quiz.index-1);await quizSave();render();break;case'submitquiz':await finishQuiz();break;case'closequiz':quiz=null;render();break;case'quizmistake':{const i=Number(d.index),q=quiz.questions[i];await record('mistake',uid(),{topic:q.topic,type:'Knowledge',error:q.text,correction:q.explanation,day:today()});toast('Correction added to your ledger.');break}case'sync':await vault.flush();break;case'lock':vault.disconnect();break;case'export':download(`group1-backup-${today()}.json`,JSON.stringify({app:'group1-sprint',version:1,exportedAt:new Date().toISOString(),events,resume:{route:route==='settings'?(state.cursor?.topic?'learn':'today'):route,topic:state.cursor?.topic||selectedTopic,step:state.cursor?.step||0}},null,2),'application/json');toast('Backup downloaded. Keep it private.');break;case'paperopen':{const p=state.papers[d.id],blob=new Blob([fromBase64(p.bytes)],{type:p.mime});download(p.filename||'paper.pdf',blob,p.mime);break}}}
function shuffle(list){const a=[...list];for(let i=a.length-1;i>0;i--){const j=crypto.getRandomValues(new Uint32Array(1))[0]%(i+1);[a[i],a[j]]=[a[j],a[i]]}return a}
function download(name,data,mime){const url=URL.createObjectURL(data instanceof Blob?data:new Blob([data],{type:mime}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000)}
async function formSubmit(f,submitter){const data=Object.fromEntries(new FormData(f));if(submitter?.name)data[submitter.name]=submitter.value;if(await features.form(f,submitter))return;switch(f.getAttribute('id')){case'comfortform':await record('reading-preferences','comfort',{theme:data.theme,font:Number(data.font),spacing:Number(data.spacing),focus:!!data.focus,motion:!!data.motion});toast('Reading comfort saved.');break;case'learningflowform':{let next={...(state.learningFlows[selectedTopic]||{topic:selectedTopic,stage:'learn',segment:0,answers:['','',''],reviewed:false,reflection:''})};if(next.stage==='recall'){next.answers=[0,1,2].map(i=>String(data['answer'+i]||''));next.reviewed=!!data.reviewed;}if(next.stage==='practice')next.reflection=String(data.reflection||'');if(data.intent==='restart')next.stage='recall';if(data.intent==='chapterstart'){next={...next,stage:'learn',segment:0,answers:['','',''],reviewed:false,reflection:'',practiceDone:false};}if(data.intent==='previous'&&next.stage==='learn')next.segment=Math.max(0,next.segment-1);if(data.intent==='advance'){if(next.stage==='learn'){if(next.segment<learningContent(selectedTopic).segments.length-1)next.segment++;else next.stage='recall';}else if(next.stage==='recall'){if(!next.reviewed||!next.answers.every(a=>a.trim().length>=10))throw Error('Try all three recall prompts and check your explanations first.');next.stage='practice';}else if(next.stage==='practice'){if(next.reflection.trim().length<10)throw Error('Record a correction or trap before finishing.');const qs=[...originalBank(),...readyQuestions(state)].filter(q=>q.topic===selectedTopic);if(qs.length&&!Object.values(state.attempts).some(a=>a.finished&&a.questions.every(q=>q.topic===selectedTopic)))throw Error('Complete topic practice first.');next.stage='revise';}}await record('learning-flow',selectedTopic,next);await record('cursor','current',{topic:selectedTopic,step:next.segment,stage:next.stage},false);if(next.stage==='revise'&&!topicDone(selectedTopic))await record('topic',selectedTopic,{done:true,day:today()});render();toast('Study flow saved. Sync and backup include your position.');break}case'planform':await record('settings','profile',{hours:Number(data.hours)},false);await record('plan','active',{start:data.start,days:Number(data.days),approved:true});location.hash='today';toast('Study plan approved.');break;case'profileform':if(data.examVerified&&(!data.examDate||!data.examSource))throw Error('Add a date and official source before marking it confirmed.');await record('settings','profile',{...data,hours:Number(data.hours),examVerified:!!data.examVerified});toast('Profile saved.');break;case'noteform':await record('note',selectedTopic,{...data,day:today()},false);await record('cursor','current',{topic:selectedTopic,step,stage:lesson.steps[step]?.heading||'notes'},false);toast('Notes and lesson position saved.');break;case'mistakeform':await record('mistake',uid(),{...data,day:today()});toast('Mistake saved.');break;case'headlineform':await record('headline',uid(),data);toast('Headline saved.');break;case'paperform':{const file=document.querySelector('#paperfile').files[0];if(file.size>4*1024*1024)throw Error('Choose a file smaller than 4 MB.');if(!['application/pdf','image/png','image/jpeg'].includes(file.type))throw Error('Use a PDF, PNG or JPEG.');await features.addPaper({...data,filename:file.name,mime:file.type,bytes:toBase64(new Uint8Array(await file.arrayBuffer()))});break}case'reviewquestion':{const q=state.questions[data.id];if(!q)throw Error('Question no longer available.');const next=data.decision==='reject'?{...q,reviewStatus:'rejected',reviewNote:data.reviewNote||'Excluded by user'}:reviewQuestion(q,{text:data.text,options:['A','B','C','D'].map(k=>data[k]),answer:Number(data.answer),answerUnknown:false,explanation:data.explanation,topic:data.topic,source:data.source,answerKeySource:data.answerKeySource,reviewNote:data.reviewNote});if(data.decision!=='reject'&&(!next.text.trim()||next.options.some(o=>!o.trim())||new Set(next.options).size!==4||!next.explanation.trim()))throw Error('Provide a question, four distinct options and an explanation.');await record('question',q.id,next);toast(data.decision==='reject'?'Question excluded from tests.':'Review saved. Question available for practice.');break}case'bankform':{const file=document.querySelector('#bankfile').files[0];if(file.size>10*1024*1024)throw Error('Question bank limit is 10 MB.');const parsed=parseBank(await file.text(),file.name.toLowerCase());const qs=parsed.filter(q=>!state.questions[q.id]).map(prepareImport);const batch=qs.map((q,i)=>({v:VERSION,id:uid(),device,clock:Math.max(0,...events.map(e=>e.clock))+i+1,at:new Date().toISOString(),type:'question',entity:q.id,data:q}));await putEvents(batch);events=mergeEvents(events,batch);state=reduce(events);channel?.postMessage('saved');render();if(vault.credentials)vault.sync();toast(`${qs.length} questions added to review; ${parsed.length-qs.length} existing IDs retained.`);break}case'syncform':{const repo=data.repo,token=data.token,passphrase=data.passphrase;f.reset();vault.connect(repo,token,passphrase);await vault.sync();break}case'importform':{const file=document.querySelector('#backupfile').files[0];if(file.size>100*1024*1024)throw Error('Backup limit is 100 MB.');const backup=JSON.parse(await file.text());if(backup.app!=='group1-sprint'||backup.version!==1||!Array.isArray(backup.events))throw Error('Unsupported backup format');const merged=mergeEvents(events,backup.events);await putEvents(backup.events);events=merged;state=reduce(events);channel?.postMessage('saved');render();if(vault.credentials)vault.sync();const target=backup.resume?.route==='learn'&&topics.some(t=>t.id===backup.resume.topic)?'learn/'+backup.resume.topic:routes.some(r=>r[0]===backup.resume?.route)?backup.resume.route:state.cursor?.topic?'learn/'+state.cursor.topic:'today';location.hash=target;toast('Backup merged. Existing events retained. Continue from your saved lesson.');break}}}
window.addEventListener('hashchange',()=>{if(Number.isInteger(history.state?.group1Depth))navDepth=history.state.group1Depth;else{navDepth++;history.replaceState({group1Depth:navDepth},'',location.href);}navigate();});window.addEventListener('online',()=>vault.sync());window.addEventListener('focus',()=>{if(vault.credentials)vault.sync()});document.addEventListener('visibilitychange',()=>{if(!document.hidden&&vault.credentials)vault.sync()});
const channel=typeof BroadcastChannel!=='undefined'?new BroadcastChannel('group1-study'):null;channel?.addEventListener('message',async()=>{events=mergeEvents(events,await getAll());state=reduce(events);refreshFromRemote()});
async function init(){navDepth=history.state?.group1Depth||0;history.replaceState({group1Depth:navDepth},'',location.href);await openDB();device=await getMeta('device');if(!device){device=uid();await setMeta('device',device)}events=await getAll();state=reduce(events);const unfinished=Object.values(state.attempts).find(a=>!a.finished);if(unfinished){quiz=structuredClone(unfinished);timerHandle=setInterval(tick,1000)}navigate();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>toast('Offline cache could not be installed; local records are still saved.'));navigator.storage?.persist?.().catch(()=>{});setInterval(()=>{if(vault.credentials&&!vault.running)vault.sync()},30000)}
init().catch(e=>{app.innerHTML=`<main class="main"><section class="card"><h1>Workspace could not open</h1><p>${esc(e.message)}</p><p>Use a browser with IndexedDB enabled. Do not clear saved browser data if you have existing progress.</p></section></main>`});

function upscTopicLinks(id){const rs=upscCatalogue.resources.filter(r=>r.appscTopics.includes(id)),qs=upscCatalogue.questions.filter(q=>q.appscTopics.includes(id));if(!rs.length&&!qs.length)return '';return `<details class="card"><summary>Related UPSC notes & questions · ${rs.length} resources · ${qs.length} questions</summary><p>Imported content is pending review. <a href="#upsc">Open UPSC question and notes library →</a></p>${rs.map(r=>`<p><a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">${esc(r.title)}</a></p>`).join('')}${qs.map(q=>`<details><summary>${esc(q.kind)} · ${esc(q.upscTopics.join(' · '))}</summary><pre class="upsc-note">${esc(q.prompt)}</pre><details><summary>Reveal imported answer · unverified</summary><pre class="upsc-note">${esc(q.answer)}</pre></details></details>`).join('')}</details>`;}


async function handleImport(d){if(d.importAction==='more')importView.limit+=20;else if(d.importAction==='questionmore')importView.questionLimit+=20;else if(d.importAction==='close'){importRequest++;importView={...importView,selected:null,data:null,loading:false,error:''};}else if(d.importAction==='open'){const doc=importIndex?.documents.find(x=>x.id===d.id);if(!doc?.dataPath)return;const id=++importRequest;importView={...importView,selected:doc,data:null,loading:true,error:'',questionQuery:'',questionLimit:20};render();try{const data=await loadCollection(fetch,doc.dataPath,doc.dataSha256);if(id!==importRequest)return;importView={...importView,data,loading:false};}catch(e){if(id!==importRequest)return;importView={...importView,error:e.message,loading:false};}}render();}
